import { createTheme } from "@mui/material";
import { themedComponents } from "./components/themedComponents";
import { getPalette } from "./palette/getPalette";
import { typography as callistoTypography } from "./typography/typography";
import { getShadows } from "./shadows/getShadows";
/**
 * Get the Original RDS theme based on the theme mode.
 * @param {ThemeMode} themeMode - corresponds to the palette being used
 * @returns {Theme} The Original RDS theme.
 */
export const getCallistoTheme = (themeMode) => {
    // Create the base color theme first, so it can be used within theme component styling.  For more info read
    // about composed themes here: https://mui.com/customization/theming/#createtheme-options-args-theme
    const baseColorTheme = createTheme({
        palette: getPalette(themeMode),
    });
    return createTheme(baseColorTheme, {
        components: themedComponents,
        shadows: getShadows(themeMode),
        shape: {
            borderRadius: 8,
        },
        typography: callistoTypography,
    });
};
